}

.error {
  border: red;
  color: red;
}

options.onRender:
// Sets the value from the first series on every refresh
const htmlgraphics = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphics) {
  values =  data.series[0]?.fields[0].values
  const status = values[values.length -1];
  htmlgraphics.textContent = status;

  if (status === 'DESACTIVED') {
        htmlgraphics.classList.remove('activate')
  } 

  else if(status === 'ACTIVED'){
    htmlgraphics.classList.add('activate')
  }

  else {
    htmlgraphics.classList.add('error')
    htmlgraphics.classList.remove('activate')
  }
}

